def categoria(servidor):
        if servidor.eh_docente:
            return "docente"
        elif servidor.eh_tecnico_administrativo:
            return "tecnico_administrativo"
        elif servidor.eh_estagiario:
            return "estagiario"
        return "indefinida"

def ajuste_novo_padrao(apps, schema):
    #
    data_limite = datetime(2024, 12, 31)
    ProcessoProgressao = apps.get_model('progressoes', 'ProcessoProgressao')
    PadraoVencimento = apps.get_model('rh', 'PadraoVencimento')
    logging.info('\n[INFO] Iniciando ajuste do novo padrão de níveis no processo de progressão TAE')
    for i in tqdm.tqdm(ProcessoProgressao.objects.filter(data_fim_contagem_progressao__gt=data_limite)):
        servidor = i.avaliado
        categoria_servidor = categoria(servidor)
        classe_nivel_posicao = servidor.cargo_classe.codigo + servidor.nivel_padrao
        classe = classe_nivel_posicao[0:1]
        posicao_vertical = classe_nivel_posicao[1:]
        try:
            padrao_vencimento, _ = PadraoVencimento.objects.get_or_create(categoria=categoria_servidor, classe=classe, posicao_vertical=posicao_vertical)
        except Exception:
            continue
        #
        posicao_vertical_proxima = int(posicao_vertical) + 1
        if posicao_vertical_proxima > 19:
            i.padrao_anterior = padrao_vencimento
            i.save()
            continue
        try:
            padrao_novo, _ = PadraoVencimento.objects.get_or_create(categoria=categoria_servidor, classe=classe, posicao_vertical=posicao_vertical_proxima)
        except Exception:
            continue
        #
        i.padrao_anterior = padrao_vencimento
        i.padrao_novo = padrao_novo
        i.save()


